17	/**
18	 * velaclaw_quickapp_bridge.c - Cross-process bridge between QuickApp feature
19	 * and the AI Agent process using POSIX message queues.
20	 *
21	 * Protocol:
22	 *   Message payload = "chat_id\ncontent" (null-terminated)
23	 *
24	 * Queues:
25	 *   /velaclaw_qapp_in   - QuickApp writes requests, Agent reads
26	 *   /velaclaw_qapp_out  - Agent writes replies, QuickApp reads
27	 */
28	
29	#include "velaclaw_quickapp_bridge.h"
30	
31	#include <errno.h>
32	#include <fcntl.h>
33	#include <mqueue.h>
34	#include <pthread.h>
35	#include <stdio.h>
36	#include <stdlib.h>
37	#include <string.h>
38	#include <syslog.h>
39	#include <unistd.h>
40	
41	/* -- Mqueue configuration (must match agent_main.c) ----------- */
42	#define VELACLAW_MQ_QAPP_IN   "/velaclaw_qapp_in"
43	#define VELACLAW_MQ_QAPP_OUT  "/velaclaw_qapp_out"
44	#define VELACLAW_MQ_MSG_SIZE  4096
45	#define VELACLAW_MQ_MAX_MSGS  4
46	
47	#define BRIDGE_TAG "[velaclaw_bridge] "
48	
49	/* -- Reply callback state ------------------------------------- */
50	static velaclaw_quickapp_reply_cb s_reply_cb;
51	static void *s_reply_userdata;
52	static pthread_t s_recv_thread;
53	static volatile int s_running;
54	
55	/* -- Receiver thread: listens for replies from agent process -- */
56	static void *bridge_recv_thread(void *arg)
57	{
58	    (void)arg;
59	
60	    struct mq_attr attr = {
61	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
62	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
63	    };
64	
65	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_OUT, O_RDONLY | O_CREAT, 0666, &attr);
66	    if (mq == (mqd_t)-1) {
67	        syslog(LOG_ERR, BRIDGE_TAG "recv: mq_open(%s) failed: %d\n",
68	               VELACLAW_MQ_QAPP_OUT, errno);
69	        return NULL;
70	    }
71	
72	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
73	    if (!buf) {
74	        syslog(LOG_ERR, BRIDGE_TAG "recv: malloc failed\n");
75	        mq_close(mq);
76	        return NULL;
77	    }
78	
79	    syslog(LOG_INFO, BRIDGE_TAG "recv thread started\n");
80	
81	    while (s_running) {
82	        ssize_t n = mq_receive(mq, buf, VELACLAW_MQ_MSG_SIZE, NULL);
83	        if (n < 0) {
84	            if (errno == EINTR) continue;
85	            syslog(LOG_ERR, BRIDGE_TAG "recv: mq_receive failed: %d\n", errno);
86	            break;
87	        }
88	
89	        /* Ensure null-termination */
90	        if (n >= (ssize_t)VELACLAW_MQ_MSG_SIZE) {
91	            n = VELACLAW_MQ_MSG_SIZE - 1;
92	        }
93	        buf[n] = '\0';
94	
95	        /* Reply format: "chat_id\ncontent" */
96	        char *sep = strchr(buf, '\n');
97	        if (!sep) {
98	            syslog(LOG_WARNING, BRIDGE_TAG "recv: malformed reply\n");
99	            continue;
100	        }
101	        *sep = '\0';
102	        const char *chat_id = buf;
103	        const char *content = sep + 1;
104	
105	        syslog(LOG_INFO, BRIDGE_TAG "recv: chat_id=%s content_len=%d\n",
106	               chat_id, (int)strlen(content));
107	
108	        if (s_reply_cb) {
109	            s_reply_cb(chat_id, content, NULL, NULL, s_reply_userdata);
110	        }
111	    }
112	
113	    free(buf);
114	    mq_close(mq);
115	    syslog(LOG_INFO, BRIDGE_TAG "recv thread exiting\n");
116	    return NULL;
117	}
118	
119	/* -- Public API ----------------------------------------------- */
120	void velaclaw_quickapp_bridge_register(velaclaw_quickapp_reply_cb cb,
121	                                       void *userdata)
122	{
123	    s_reply_cb = cb;
124	    s_reply_userdata = userdata;
125	
126	    if (!s_running) {
127	        s_running = 1;
128	
129	        pthread_attr_t attr;
130	        pthread_attr_init(&attr);
131	        pthread_attr_setstacksize(&attr, 4096);
132	        pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
133	
134	        int ret = pthread_create(&s_recv_thread, &attr, bridge_recv_thread, NULL);
135	        pthread_attr_destroy(&attr);
136	
137	        if (ret != 0) {
138	            syslog(LOG_ERR, BRIDGE_TAG "failed to create recv thread: %d\n", ret);
139	            s_running = 0;
140	        }
141	    }
142	}
143	
144	void velaclaw_quickapp_bridge_unregister(void)
145	{
146	    s_reply_cb = NULL;
147	    s_reply_userdata = NULL;
148	    s_running = 0;
149	}
