151	int velaclaw_quickapp_bridge_ask(const char *chat_id, const char *query)
152	{
153	    if (!query || !query[0]) {
154	        return -EINVAL;
155	    }
156	    if (!chat_id || !chat_id[0]) {
157	        return -EINVAL;
158	    }
159	
160	    struct mq_attr attr = {
161	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
162	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
163	    };
164	
165	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_IN, O_WRONLY | O_CREAT, 0666, &attr);
166	    if (mq == (mqd_t)-1) {
167	        syslog(LOG_ERR, BRIDGE_TAG "ask: mq_open(%s) failed: %d\n",
168	               VELACLAW_MQ_QAPP_IN, errno);
169	        return -ENOTCONN;
170	    }
171	
172	    /* Build payload: "chat_id\nquery" */
173	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
174	    if (!buf) {
175	        mq_close(mq);
176	        return -ENOMEM;
177	    }
178	
179	    int len = snprintf(buf, VELACLAW_MQ_MSG_SIZE, "%s\n%s", chat_id, query);
180	    if (len >= (int)VELACLAW_MQ_MSG_SIZE) {
181	        len = VELACLAW_MQ_MSG_SIZE - 1;
182	        buf[len] = '\0';
183	    }
184	
185	    int ret = 0;
186	    if (mq_send(mq, buf, len + 1, 0) != 0) {
187	        syslog(LOG_ERR, BRIDGE_TAG "ask: mq_send failed: %d\n", errno);
188	        ret = -errno;
189	    } else {
190	        syslog(LOG_INFO, BRIDGE_TAG "ask: sent chat_id=%s query_len=%d\n",
191	               chat_id, (int)strlen(query));
192	    }
193	
194	    free(buf);
195	    mq_close(mq);
196	    return ret;
197	}
198	
199	/* -- Utility functions ---------------------------------------- */
200	int velaclaw_quickapp_bridge_get_status(char *output, size_t output_size)
201	{
202	    if (!output || output_size == 0) {
203	        return -EINVAL;
204	    }
205	    snprintf(output, output_size,
206	             "{\"ok\":true,\"bridge\":\"mqueue\",\"running\":%s}",
207	             s_running ? "true" : "false");
208	    return 0;
209	}
