211	int velaclaw_quickapp_bridge_call_tool(const char *app_id,
212	                                       const char *tool,
213	                                       const char *args_json,
214	                                       char *output,
215	                                       size_t output_size)
216	{
217	    (void)app_id;
218	    (void)tool;
219	    (void)args_json;
220	
221	    if (!output || output_size == 0) {
222	        return -EINVAL;
223	    }
224	    snprintf(output, output_size,
225	             "{\"ok\":false,\"code\":\"not_implemented\","
226	             "\"message\":\"tool calling not supported via mqueue bridge\"}");
227	    return -ENOSYS;
228	}
