451	/* ── Startup timing helpers ───────────────────────────────────── */
452	
453	static inline long boot_ms(struct timespec* t0)
454	{
455	    struct timespec now;
456	    clock_gettime(CLOCK_MONOTONIC, &now);
457	    return (long)((now.tv_sec - t0->tv_sec) * 1000L + (now.tv_nsec - t0->tv_nsec) / 1000000L);
458	}
459	
460	#define BOOT_LOG(t0, phase, msg) \
461	    syslog(LOG_INFO, "[%s] [boot +%ldms] " phase ": " msg "\n", TAG, boot_ms(t0))
462	
463	#define BOOT_LOG_RC(t0, phase, msg, rc) \
464	    syslog((rc) == OK ? LOG_INFO : LOG_WARNING, \
465	        "[%s] [boot +%ldms] " phase ": " msg " (rc=%d)\n", TAG, boot_ms(t0), (rc))
466	
467	int ai_agent_main(int argc, char* argv[])
468	{
469	    (void)argc;
470	    (void)argv;
471	
472	    g_shutdown_requested = false;
473	
474	    struct timespec t0;
475	    clock_gettime(CLOCK_MONOTONIC, &t0);
476	
477	    syslog(LOG_INFO, "[%s] AI Agent - Vela AI Agent starting (build: %s)\n",
478	        TAG, AGENT_BUILD_VERSION);
479	
480	    /* ── Phase 0: Timezone ──────────────────────────────────── */
481	    /* Set TZ before any time calls so localtime_r returns CST+8.
482	     * NuttX with CONFIG_LIBC_LOCALTIME+CONFIG_LIBC_ZONEINFO supports
483	     * both POSIX ("CST-8") and zoneinfo ("Asia/Shanghai") formats. */
484	    setenv("TZ", AGENT_TIMEZONE, 1);
485	#ifdef CONFIG_LIBC_LOCALTIME
486	    tzset();
487	#endif
488	    BOOT_LOG(&t0, "P0", "timezone set");
489	
490	    /* ── Phase 0: Storage Bootstrapping (Auto-mount & Mkdir) ── */
491	
492	    struct stat st;
493	    if (stat("/data", &st) != 0) {
494	        syslog(LOG_INFO, "[%s] Mounting /data as tmpfs for simulation...\n", TAG);
495	        mount(NULL, "/data", "tmpfs", 0, NULL);
496	    }
497	
498	    /* Ensure directory structure exists (No more manual mkdir needed!) */
499	    mkdir("/data/agent", 0755);
500	    mkdir("/data/agent/config", 0755);
501	    mkdir("/data/agent/memory", 0755);
502	    mkdir("/data/agent/sessions", 0755);
503	    mkdir("/data/agent/skills", 0755);
504	    BOOT_LOG(&t0, "P0", "storage ready");
505	
506	    /* Memory info */
507	    {
508	        struct mallinfo mi = mallinfo();
509	        syslog(LOG_INFO, "[%s] [boot +%ldms] heap: arena=%d free=%d used=%d\n",
510	            TAG, boot_ms(&t0), mi.arena, mi.fordblks, mi.uordblks);
511	    }
512	
513	    /* ── Phase 1: Core infrastructure ──────────────────────── */
514	    {
515	        int rc;
516	        rc = config_store_init();
517	        BOOT_LOG_RC(&t0, "P1", "config_store_init", rc);
518	
519	        rc = message_bus_init();
520	        BOOT_LOG_RC(&t0, "P1", "message_bus_init", rc);
521	        if (rc != OK)
522	            return -1;
523	
524	        rc = memory_store_init();
525	        BOOT_LOG_RC(&t0, "P1", "memory_store_init", rc);
526	
527	        rc = session_mgr_init();
528	        BOOT_LOG_RC(&t0, "P1", "session_mgr_init", rc);
529	    }
530	
531	    /* ── Phase 2: Proxy / networking ───────────────────────── */
532	    {
533	        int rc = http_proxy_init();
534	        BOOT_LOG_RC(&t0, "P2", "http_proxy_init", rc);
535	    }
536	
537	    /* ── Phase 3: Application services ─────────────────────── */
538	    {
539	        int rc;
540	#ifdef CONFIG_AI_AGENT_FEISHU
541	        rc = feishu_bot_init();
542	        BOOT_LOG_RC(&t0, "P3", "feishu_bot_init", rc);
543	#endif
544	
545	        rc = llm_proxy_init();
546	        BOOT_LOG_RC(&t0, "P3", "llm_proxy_init", rc);
547	
548	        rc = llm_router_init();
549	        BOOT_LOG_RC(&t0, "P3", "llm_router_init", rc);
550	
551	        /* node_manager must init BEFORE tool_registry so it can
552	         * register itself as a tool provider. */
553	#ifdef CONFIG_AI_AGENT_NODE
554	        rc = node_manager_init();
555	        BOOT_LOG_RC(&t0, "P3", "node_manager_init", rc);
556	#endif
557	
558	        rc = tool_registry_init();
559	        BOOT_LOG_RC(&t0, "P3", "tool_registry_init", rc);
560	
561	        rc = tool_guard_init();
562	        BOOT_LOG_RC(&t0, "P3", "tool_guard_init", rc);
563	
564	        /* Skills must init AFTER tool_registry so executable skills
565	         * can register themselves as tools. */
566	        rc = skill_loader_init();
567	        BOOT_LOG_RC(&t0, "P3", "skill_loader_init", rc);
568	
569	        rc = agent_loop_init();
570	        BOOT_LOG_RC(&t0, "P3", "agent_loop_init", rc);
571	
572	        rc = cron_service_init();
573	        BOOT_LOG_RC(&t0, "P3", "cron_service_init", rc);
574	
575	        rc = heartbeat_init();
576	        BOOT_LOG_RC(&t0, "P3", "heartbeat_init", rc);
577	
578	#ifdef CONFIG_AI_AGENT_NODE
579	        rc = node_client_init();
580	        BOOT_LOG_RC(&t0, "P3", "node_client_init", rc);
581	#endif
582	
583	#ifdef CONFIG_AI_AGENT_MQTT
584	        rc = mqtt_channel_init();
585	        BOOT_LOG_RC(&t0, "P3", "mqtt_channel_init", rc);
586	#endif
587	
588	        rc = voice_channel_init();
589	        BOOT_LOG_RC(&t0, "P3", "voice_channel_init", rc);
590	
591	#ifdef CONFIG_AI_AGENT_WEIXIN
592	        rc = weixin_channel_init();
593	        BOOT_LOG_RC(&t0, "P3", "weixin_channel_init", rc);
594	#endif
595	
596	#ifdef CONFIG_AI_AGENT_LVGL_UI
597	        rc = lvgl_ui_channel_init();
598	        BOOT_LOG_RC(&t0, "P3", "lvgl_ui_channel_init", rc);
599	#endif
600	    }
601	
602	    /* ── Phase 4: CLI — register commands only, no thread yet ── */
603	    {
604	        int rc = nsh_commands_init();
605	        BOOT_LOG_RC(&t0, "P4", "nsh_commands_init", rc);
606	    }
607	
608	    /* ── Phase 5: Network — async, does NOT block ready ────── */
609	
610	    /* Kick off WiFi reconnect and start outbound dispatch immediately.
611	     * Network-dependent services (feishu, agent, ws, node) are started
612	     * inside the network_watch thread once the link comes up. */
613	
614	    /* Outbound dispatch thread — start before network so queued messages
615	     * are drained even during the connection window. */
616	    if (agent_task_create(outbound_dispatch_task, "outbound",
617	            AGENT_OUTBOUND_STACK, NULL,
618	            AGENT_OUTBOUND_PRIO)
619	        != OK) {
620	        syslog(LOG_ERR, "[%s] Failed to start outbound dispatch thread\n", TAG);
621	        return -1;
622	    }
623	    BOOT_LOG(&t0, "P5", "outbound dispatch thread started");
624	
625	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
626	    /* Quickapp mqueue listener - receives requests from quickapp process */
627	    if (agent_task_create(quickapp_mq_listener_task, "qapp_mq",
628	                         AGENT_OUTBOUND_STACK, NULL,
629	                         AGENT_OUTBOUND_PRIO) != OK) {
630	        syslog(LOG_WARNING, "[%s] Failed to start quickapp mqueue listener\n", TAG);
631	    }
632	    BOOT_LOG(&t0, "P5", "quickapp mqueue listener started");
633	#endif
634	
635	    /* Cron + heartbeat don't need network */
636	    cron_service_start();
637	    heartbeat_start();
638	    BOOT_LOG(&t0, "P5", "cron + heartbeat started");
639	
640	#ifdef CONFIG_AI_AGENT_LVGL_UI
641	    if (lvgl_ui_channel_start() != OK)
642	        syslog(LOG_WARNING, "[%s] lvgl_ui_channel_start failed\n", TAG);
643	    BOOT_LOG(&t0, "P5", "lvgl_ui_channel started");
644	#endif
645	
646	#ifdef CONFIG_AI_AGENT_BLE_GATT
647	    /* BLE GATT: ensure adapter enabled, then init with retries */
648	    {
649	        extern void ble_cmd_handler_recv(const uint8_t* data, uint16_t len,
650	            void* user_data);
651	        bt_instance_t* bt_ins = bluetooth_get_instance();
652	        if (bt_ins) {
653	            bt_adapter_state_t state = bt_adapter_get_state(bt_ins);
654	            if (state < BT_ADAPTER_STATE_BLE_ON) {
655	                syslog(LOG_INFO, "[%s] BT not ready (state=%d), enabling LE...\n",
656	                    TAG, (int)state);
657	                bt_adapter_enable_le(bt_ins);
658	                sleep(2);
659	            }
660	        }
661	
662	        ble_gatt_config_t ble_cfg = {
663	            .device_name = "VelaClaw",
664	            .recv_cb = ble_cmd_handler_recv,
665	        };
666	        int rc = -1;
667	        int attempts = 0;
668	        while (rc < 0 && attempts < 5) {
669	            rc = ble_gatt_init(&ble_cfg);
670	            if (rc < 0) {
671	                syslog(LOG_WARNING, "[%s] ble_gatt_init attempt %d failed: %d\n",
672	                    TAG, attempts + 1, rc);
673	                sleep(3);
674	            }
675	            attempts++;
676	        }
677	        if (rc == 0) {
678	            BOOT_LOG(&t0, "P5", "ble_gatt init OK");
679	        } else {
680	            BOOT_LOG(&t0, "P5", "ble_gatt FAILED after retries");
681	        }
682	    }
683	#endif
684	
685	    /* Network watcher thread: reconnect + wait + start net services */
686	    if (agent_task_create(network_watch_task, "net_watch",
687	            AGENT_OUTBOUND_STACK, NULL,
688	            AGENT_OUTBOUND_PRIO)
689	        != OK) {
690	        syslog(LOG_WARNING, "[%s] Failed to start network_watch thread\n", TAG);
691	    }
692	    BOOT_LOG(&t0, "P5", "network_watch thread started (async)");
693	
694	    /* ── Phase 6: CLI thread — all services now in known state ── */
695	    {
696	        int rc = nsh_commands_start();
697	        BOOT_LOG_RC(&t0, "P6", "nsh_commands_start", rc);
698	    }
699	
700	    syslog(LOG_INFO, "[%s] [boot +%ldms] AI Agent ready. Type 'help' in NSH for commands.\n",
701	        TAG, boot_ms(&t0));
702	
703	    /* Block main thread until shutdown is requested */
704	    while (!g_shutdown_requested) {
705	        sleep(1);
706	    }
707	
708	    syslog(LOG_INFO, "[%s] Shutdown requested — stopping services...\n", TAG);
709	
710	    /* Wake all threads blocked on message bus before stopping services */
711	    message_bus_wakeup();
712	
713	    /* ── Graceful teardown (reverse of startup order) ──────── */
714	
715	    /* Phase 5 services (network-dependent) */
716	#ifdef CONFIG_AI_AGENT_WEIXIN
717	    weixin_channel_stop();
718	#endif
719	#ifdef CONFIG_AI_AGENT_NODE
720	    node_client_stop();
721	#endif
722	#ifdef CONFIG_AI_AGENT_MQTT
723	    mqtt_channel_stop();
724	#endif
725	    ws_server_stop();
726	    /* feishu_bot and agent_loop have no _stop(); they will exit
727	     * naturally once their blocking I/O returns an error after
728	     * the network sockets are closed below, or they can check
729	     * agent_shutdown_requested() in their loops. */
730	
731	#ifdef CONFIG_AI_AGENT_LVGL_UI
732	    lvgl_ui_channel_stop();
733	#endif
734	
735	    /* Phase 5 services (non-network) */
736	    cron_service_stop();
737	    heartbeat_stop();
738	
739	    /* Give threads a moment to notice and exit */
740	    usleep(500 * 1000);
741	
742	    /* Cleanup — reverse order of init */
743	    tool_media_cleanup();
744	#ifdef CONFIG_AI_AGENT_MCP
745	    mcp_bridge_cleanup();
746	#endif
747	    tool_guard_cleanup();
748	    tool_registry_cleanup();
749	    llm_cache_cleanup();
750	    vela_tls_pool_cleanup();
751	    message_bus_destroy();
752	
753	    syslog(LOG_INFO, "[%s] Shutdown complete.\n", TAG);
754	
755	    return 0;
756	}
