77	/* -- Helper: allocate a FeatureMalloc string ------------------ */
78	
79	static char* ft_strdup(const char* src)
80	{
81	    if (!src) return nullptr;
82	    size_t len = strlen(src);
83	    char* s = (char*)FeatureMalloc(len + 1, FT_STRING);
84	    if (s) {
85	        memcpy(s, src, len);
86	        s[len] = '\0';
87	    }
88	    return s;
89	}
