91	/* -- Async queue callback (runs on JS/UV loop thread) --------- */
92	
93	static void async_reply_cb(uv_async_queue_t* queue, void* data)
94	{
95	    AsyncReply* reply = static_cast<AsyncReply*>(data);
96	    if (!reply) return;
97	
98	    VELACLAW_INFO("async_reply_cb: chat_id=%s content_len=%d tc=%s",
99	                  reply->chat_id ? reply->chat_id : "null",
100	                  reply->content ? (int)strlen(reply->content) : 0,
101	                  reply->tool_calls ? "yes" : "no");
102	
103	    {
104	        std::lock_guard<std::mutex> lock(s_ask_mutex);
105	        auto it = s_pending_asks.find(reply->chat_id ? reply->chat_id : "");
106	        if (it != s_pending_asks.end()) {
107	            PendingAsk ask = it->second;
108	            s_pending_asks.erase(it);
109	
110	            if (!FeatureInstanceIsDetached(ask.feature)) {
111	                system_velaclaw_AskResponse* response = system_velaclawMallocAskResponse();
112	                if (response) {
113	                    response->reply = ft_strdup(reply->content ? reply->content : "");
114	
115	                    /* Fill extra_info if present */
116	                    if (reply->extra_info && reply->extra_info[0]) {
117	                        response->extra_info = ft_strdup(reply->extra_info);
118	                    } else {
119	                        response->extra_info = NULL;
120	                    }
121	
122	                    /* Parse tool_calls JSON array into ToolCallResult[] */
123	                    int tc_count = 0;
124	                    cJSON* tc_arr = nullptr;
125	                    if (reply->tool_calls && reply->tool_calls[0]) {
126	                        tc_arr = cJSON_Parse(reply->tool_calls);
127	                        if (tc_arr && cJSON_IsArray(tc_arr)) {
128	                            tc_count = cJSON_GetArraySize(tc_arr);
129	                        }
130	                    }
131	
132	                    if (tc_count > 0) {
133	                        FtArray* arr = system_velaclaw_malloc_ToolCallResult_struct_type_array();
134	                        if (arr) {
135	                            for (int i = 0; i < tc_count; i++) {
136	                                cJSON* tc = cJSON_GetArrayItem(tc_arr, i);
137	                                system_velaclaw_ToolCallResult* item =
138	                                    system_velaclawMallocToolCallResult();
139	                                if (!item) continue;
140	
141	                                cJSON* name_item = cJSON_GetObjectItem(tc, "name");
142	                                item->name = ft_strdup(
143	                                    (name_item && cJSON_IsString(name_item))
144	                                    ? name_item->valuestring : "");
145	
146	                                /* result is a JSON object - serialize to string */
147	                                cJSON* result_item = cJSON_GetObjectItem(tc, "result");
148	                                if (result_item) {
149	                                    char* rs = cJSON_PrintUnformatted(result_item);
150	                                    item->result = ft_strdup(rs ? rs : "");
151	                                    free(rs);
152	                                } else {
153	                                    item->result = ft_strdup("");
154	                                }
155	
156	                                FeatureArrayAppend(arr, item);
157	                            }
158	                            response->tool_calls = arr;
159	                        }
160	                    } else {
161	                        /* Default to empty array so JS always gets [] */
162	                        response->tool_calls =
163	                            system_velaclaw_malloc_ToolCallResult_struct_type_array();
164	                    }
165	
166	                    if (tc_arr) cJSON_Delete(tc_arr);
167	
168	                    FeaturePromiseResolve(ask.feature, ask.pid, response);
169	                    FeatureFreeValue(response);
170	                } else {
171	                    FeaturePromiseReject(ask.feature, ask.pid,
172	                        VELACLAW_ERR_GENERAL, "Failed to allocate response");
173	                }
174	            }
175	            FeatureFreeInstanceHandle(ask.feature);
176	            free(reply->chat_id);
177	            free(reply->content);
178	            free(reply->extra_info);
179	            free(reply->tool_calls);
180	            free(reply);
181	            return;
182	        }
183	    }
184	
185	    free(reply->chat_id);
186	    free(reply->content);
187	    free(reply->extra_info);
188	    free(reply->tool_calls);
189	    free(reply);
190	}
