192	/* -- Bridge callback (called from bridge receiver thread) ----- */
193	
194	static VelaclawContext* s_proto_ctx = nullptr;
195	
196	static void quickapp_reply_handler(const char* chat_id, const char* content,
197	                                   const char* extra_info,
198	                                   const char* tool_calls, void* userdata)
199	{
200	    VELACLAW_INFO("reply_handler: chat_id=%s content_len=%d tc=%s",
201	                  chat_id ? chat_id : "null",
202	                  content ? (int)strlen(content) : 0,
203	                  tool_calls ? "yes" : "no");
204	
205	    AsyncReply* reply = static_cast<AsyncReply*>(malloc(sizeof(AsyncReply)));
206	    if (!reply) {
207	        VELACLAW_ERROR("reply_handler: failed to allocate AsyncReply");
208	        return;
209	    }
210	    reply->chat_id = strdup(chat_id ? chat_id : "");
211	    reply->content = strdup(content ? content : "");
212	    reply->extra_info = extra_info && extra_info[0] ? strdup(extra_info) : NULL;
213	    reply->tool_calls = (tool_calls && tool_calls[0]) ? strdup(tool_calls) : nullptr;
214	
215	    VelaclawContext* ctx = static_cast<VelaclawContext*>(userdata);
216	    if (ctx && ctx->initialized) {
217	        uv_async_queue_send(&ctx->async_queue, reply);
218	    } else {
219	        VELACLAW_ERROR("reply_handler: context not initialized, dropping reply");
220	        free(reply->chat_id);
221	        free(reply->content);
222	        free(reply->extra_info);
223	        free(reply->tool_calls);
224	        free(reply);
225	    }
226	}
