235	void system_velaclaw_onCreate(FeatureRuntimeContext ctx, FeatureProtoHandle handle)
236	{
237	    VELACLAW_DEBUG("onCreate");
238	    VelaclawContext* context = new VelaclawContext();
239	    if (!context) {
240	        VELACLAW_ERROR("Failed to allocate VelaclawContext");
241	        return;
242	    }
243	    context->initialized = false;
244	    context->async_queue.data = context;
245	
246	    FeatureManagerHandle manager = FeatureGetManagerHandleFromProto(handle);
247	    int ret = uv_async_queue_init(FeatureGetUVLoop(manager),
248	                                  &context->async_queue, async_reply_cb);
249	    if (ret != 0) {
250	        VELACLAW_ERROR("uv_async_queue_init failed: %d", ret);
251	        delete context;
252	        return;
253	    }
254	    context->initialized = true;
255	
256	    s_proto_ctx = context;
257	    velaclaw_quickapp_bridge_register(quickapp_reply_handler, context);
258	
259	    FeatureSetProtoData(handle, context);
260	}
