267	void system_velaclaw_onDetached(FeatureRuntimeContext ctx, FeatureInstanceHandle handle)
268	{
269	    VELACLAW_DEBUG("onDetached");
270	
271	    /* Clean up pending asks for this instance */
272	    {
273	        std::lock_guard<std::mutex> lock(s_ask_mutex);
274	        for (auto it = s_pending_asks.begin(); it != s_pending_asks.end(); ) {
275	            if (it->second.feature == handle) {
276	                FeatureFreeInstanceHandle(it->second.feature);
277	                it = s_pending_asks.erase(it);
278	            } else {
279	                ++it;
280	            }
281	        }
282	    }
283	}
