312	/* -- API: ask ------------------------------------------------- */
313	
314	void system_velaclaw_wrap_ask(FeatureInstanceHandle feature, AppendData append_data,
315	                               FtPromiseId pid, system_velaclaw_AskParam* param)
316	{
317	    VELACLAW_INFO("ask: query=%s", param->query ? param->query : "null");
318	
319	    ft_context_ref ft_ctx = FeatureGetContext(feature);
320	
321	    /* Validate query */
322	    if (!param->query || strlen(param->query) == 0) {
323	        FeaturePromiseReject(feature, pid, VELACLAW_ERR_PARAM, "query is required");
324	        return;
325	    }
326	
327	    /* Generate unique chat_id for this request */
328	    uint32_t id = s_req_id.fetch_add(1);
329	    char chat_id[64];
330	    snprintf(chat_id, sizeof(chat_id), "qapp_ask_%u", id);
331	
332	    /* Store pending request */
333	    {
334	        std::lock_guard<std::mutex> lock(s_ask_mutex);
335	        PendingAsk ask;
336	        ask.feature = FeatureDupInstanceHandle(feature);
337	        ask.pid = pid;
338	        ask.ft_ctx = ft_ctx;
339	        s_pending_asks[chat_id] = ask;
340	        VELACLAW_INFO("ask: pending count=%d chat_id=%s",
341	                      (int)s_pending_asks.size(), chat_id);
342	    }
343	
344	    /* Send to agent via bridge */
345	    int ret = velaclaw_quickapp_bridge_ask(chat_id, param->query);
346	    VELACLAW_INFO("ask: bridge_ask returned %d", ret);
347	    if (ret != 0) {
348	        std::lock_guard<std::mutex> lock(s_ask_mutex);
349	        auto it = s_pending_asks.find(chat_id);
350	        if (it != s_pending_asks.end()) {
351	            FeatureFreeInstanceHandle(it->second.feature);
352	            s_pending_asks.erase(it);
353	        }
354	        FeaturePromiseReject(feature, pid, VELACLAW_ERR_SERVICE_UNAVAIL,
355	                            "Failed to send query to AI agent");
356	    }
357	}
