68	/* ── Clock-safe elapsed time calculation ───────────────────── */
69	
70	static inline uint32_t calc_elapsed_ms(const struct timeval* t0,
71	    const struct timeval* t1)
72	{
73	    int32_t sec_diff = (int32_t)(t1->tv_sec - t0->tv_sec);
74	    int32_t usec_diff = (int32_t)(t1->tv_usec - t0->tv_usec);
75	
76	    /* Clock went backwards (NTP jump, manual adjustment) */
77	    if (sec_diff < 0) {
78	        syslog(LOG_WARNING, "[%s] Clock went backwards, ignoring\n", TAG);
79	        return 0;
80	    }
81	
82	    /* Microsecond borrow */
83	    if (usec_diff < 0) {
84	        sec_diff--;
85	        usec_diff += 1000000;
86	    }
87	
88	    if (sec_diff < 0) {
89	        return 0;
90	    }
91	
92	    return (uint32_t)sec_diff * 1000 + (uint32_t)usec_diff / 1000;
93	}
