165	/* Parallel tool execution context */
166	typedef struct {
167	    const llm_tool_call_t* call;
168	    char* output;
169	    size_t output_size;
170	    bool from_pool;
171	    char channel[16];
172	    char chat_id[64];
173	} tool_task_t;
174	
175	static void* tool_exec_thread(void* arg)
176	{
177	    tool_task_t* t = (tool_task_t*)arg;
178	
179	    t->output[0] = '\0';
180	    char* patched = inject_cron_context(
181	        t->call->name, t->call->input, t->channel, t->chat_id);
182	    agent_tool_exec_streamed(t->call->name,
183	        patched ? patched : t->call->input,
184	        t->output, t->output_size);
185	    free(patched);
186	    syslog(LOG_INFO, "[%s] Tool %s result: %d bytes\n",
187	        TAG, t->call->name, (int)strlen(t->output));
188	    return NULL;
189	}
190	
191	/* Add one role:"tool" message per tool result (OpenAI format).
192	 * When call_count > 1, all tools run in parallel threads.
193	 * Uses memory pool for parallel buffers, with heap fallback. */
194	static void add_tool_result_messages(cJSON* messages,
195	    const llm_response_t* resp, char* tool_output,
196	    size_t tool_output_size, const char* msg_channel,
197	    const char* msg_chat_id)
198	{
199	    int n = resp->call_count;
200	
201	    if (n == 1) {
202	        const llm_tool_call_t* call = &resp->calls[0];
203	
204	        syslog(LOG_INFO, "[%s] Tool call: %s args=%.500s\n", TAG,
205	            call->name, call->input ? call->input : "(null)");
206	        tool_output[0] = '\0';
207	        char* patched = inject_cron_context(
208	            call->name, call->input, msg_channel, msg_chat_id);
209	        agent_tool_exec_streamed(call->name,
210	            patched ? patched : call->input,
211	            tool_output, tool_output_size);
212	        free(patched);
213	        syslog(LOG_INFO, "[%s] Tool %s result: %d bytes\n", TAG,
214	            call->name, (int)strlen(tool_output));
215	
216	        cJSON* result_msg = cJSON_CreateObject();
217	        cJSON_AddStringToObject(result_msg, "role", "tool");
218	        cJSON_AddStringToObject(result_msg, "tool_call_id", call->id);
219	        cJSON_AddStringToObject(result_msg, "content", tool_output);
220	        cJSON_AddItemToArray(messages, result_msg);
221	        return;
222	    }
223	
224	    /* Parallel path */
225	    tool_task_t tasks[AGENT_MAX_TOOL_CALLS];
226	    pthread_t threads[AGENT_MAX_TOOL_CALLS];
227	    size_t par_buf_size = agent_mem_safe_size(
228	        TOOL_OUTPUT_SIZE_LARGE, TOOL_OUTPUT_SIZE_MIN);
229	
230	    for (int i = 0; i < n; i++) {
231	        tasks[i].call = &resp->calls[i];
232	        strncpy(tasks[i].channel, msg_channel ? msg_channel : "",
233	            sizeof(tasks[i].channel) - 1);
234	        strncpy(tasks[i].chat_id, msg_chat_id ? msg_chat_id : "",
235	            sizeof(tasks[i].chat_id) - 1);
236	
237	        char* buf = s_pool_ready
238	            ? agent_pool_acquire(&s_tool_pool)
239	            : NULL;
240	        if (buf) {
241	            tasks[i].output = buf;
242	            tasks[i].output_size = s_tool_pool.buf_size;
243	            tasks[i].from_pool = true;
244	        } else {
245	            tasks[i].output = calloc(1, par_buf_size);
246	            tasks[i].output_size = par_buf_size;
247	            tasks[i].from_pool = false;
248	        }
249	
250	        if (!tasks[i].output) {
251	            threads[i] = 0;
252	            continue;
253	        }
254	
255	        pthread_attr_t attr;
256	        pthread_attr_init(&attr);
257	        pthread_attr_setstacksize(&attr, 16 * 1024);
258	        if (pthread_create(&threads[i], &attr,
259	                tool_exec_thread, &tasks[i])
260	            != 0) {
261	            syslog(LOG_ERR, "[%s] Failed to spawn thread for tool %s\n",
262	                TAG, resp->calls[i].name);
263	            threads[i] = 0;
264	        }
265	        pthread_attr_destroy(&attr);
266	    }
267	
268	    /* Join and collect results, dedup by tool_call_id */
269	    char seen_ids[AGENT_MAX_TOOL_CALLS][32];
270	    int seen_count = 0;
271	
272	    for (int i = 0; i < n; i++) {
273	        if (threads[i]) {
274	            pthread_join(threads[i], NULL);
275	        }
276	
277	        bool dup = false;
278	        for (int j = 0; j < seen_count; j++) {
279	            if (strcmp(seen_ids[j], resp->calls[i].id) == 0) {
280	                dup = true;
281	                break;
282	            }
283	        }
284	
285	        if (dup) {
286	            syslog(LOG_WARNING,
287	                "[%s] Skipping duplicate tool_call_id: %s\n",
288	                TAG, resp->calls[i].id);
289	        } else {
290	            strncpy(seen_ids[seen_count++], resp->calls[i].id,
291	                sizeof(seen_ids[0]) - 1);
292	
293	            cJSON* result_msg = cJSON_CreateObject();
294	            cJSON_AddStringToObject(result_msg, "role", "tool");
295	            cJSON_AddStringToObject(result_msg, "tool_call_id",
296	                resp->calls[i].id);
297	            cJSON_AddStringToObject(result_msg, "content",
298	                (tasks[i].output && tasks[i].output[0])
299	                    ? tasks[i].output
300	                    : "{}");
301	            cJSON_AddItemToArray(messages, result_msg);
302	        }
303	
304	        if (tasks[i].from_pool) {
305	            agent_pool_release(&s_tool_pool, tasks[i].output);
306	        } else {
307	            free(tasks[i].output);
308	        }
309	    }
310	}
