317	/* ── Natural language fast path (keyword → direct tool call) ── */
318	
319	static bool contains_any(const char* text, const char** keywords)
320	{
321	    for (int i = 0; keywords[i]; i++) {
322	        if (strcasestr(text, keywords[i])) {
323	            return true;
324	        }
325	    }
326	    return false;
327	}
