329	/* Intent table: each entry maps keywords → tool + args + output size */
330	
331	typedef struct {
332	    const char** keywords;
333	    const char* tool_name;
334	    const char* tool_args;
335	    size_t output_size;
336	} nl_intent_t;
337	
338	static const char* kw_time[]       = { "几点了", "什么时间", "what time", "几点钟", NULL };
339	static const char* kw_battery[]    = { "电量多少", "电池电量", "battery", NULL };
340	static const char* kw_heartrate[]  = { "心率多少", "heart rate", "心率是多", NULL };
341	static const char* kw_steps[]      = { "走了多少步", "今天走了多少", "steps", "步数", NULL };
342	static const char* kw_pause[]      = { "暂停音乐", "暂停播放", "pause music", NULL };
343	static const char* kw_stop[]       = { "停止播放", "停止音乐", "stop music", NULL };
344	static const char* kw_resume[]     = { "继续播放", "resume", NULL };
345	
346	static const nl_intent_t s_intents[] = {
347	    { kw_time,      "get_current_time", "{}",  256  },
348	    { kw_battery,   "get_battery",      "{}",  512  },
349	    { kw_heartrate, "get_heartrate",    "{}",  256  },
350	    { kw_steps,     "get_steps",        "{}",  256  },
351	    { kw_pause,     "music_pause",      "{}",  256  },
352	    { kw_stop,      "music_stop",       "{}",  256  },
353	    { kw_resume,    "music_resume",     "{}",  256  },
354	    { NULL,         NULL,               NULL,  0    },
355	};
