357	static char* handle_nl_fast_path(const char* text)
358	{
359	    /* Table-driven: scan intents, first match wins */
360	    for (int i = 0; s_intents[i].keywords; i++) {
361	        if (contains_any(text, s_intents[i].keywords)) {
362	            char* reply = calloc(1, s_intents[i].output_size);
363	            if (reply) {
364	                tool_registry_execute(s_intents[i].tool_name,
365	                    s_intents[i].tool_args, reply,
366	                    s_intents[i].output_size);
367	            }
368	            if (reply) {
369	                s_fast_path_count++;
370	                syslog(LOG_INFO,
371	                    "[%s] NL fast path: %s (fast=%d llm=%d)\n",
372	                    TAG, s_intents[i].tool_name,
373	                    s_fast_path_count, s_llm_path_count);
374	            }
375	            return reply;
376	        }
377	    }
378	
379	    /* Skill list (special: no tool call) */
380	    static const char* kw_skill[] = {
381	        "技能列表", "有什么技能", "list skill", NULL };
382	    if (contains_any(text, kw_skill)) {
383	        char buf[2048];
384	        size_t n = skill_loader_build_summary(buf, sizeof(buf));
385	        s_fast_path_count++;
386	        return n > 0 ? strdup(buf) : strdup("暂无已加载的技能。");
387	    }
388	
389	    /* Weather (special: needs city extraction) */
390	    static const char* kw_weather[] = {
391	        "天气怎么样", "weather", "天气如何", NULL };
392	    if (contains_any(text, kw_weather)) {
393	        char safe_city[64];
394	        strncpy(safe_city, "Beijing", sizeof(safe_city) - 1);
395	        safe_city[sizeof(safe_city) - 1] = '\0';
396	
397	        const char* p = strstr(text, "天气");
398	        if (p && p > text && (size_t)(p - text) < sizeof(safe_city) - 1) {
399	            int ci = 0;
400	            for (const char* s = text; s < p && ci < 62; s++) {
401	                if (*s != '"' && *s != '\\' && *s != ' ')
402	                    safe_city[ci++] = *s;
403	            }
404	            if (ci > 0) safe_city[ci] = '\0';
405	        }
406	
407	        char input[256];
408	        snprintf(input, sizeof(input),
409	            "{\"location\":\"%s\"}", safe_city);
410	        char* reply = calloc(1, 4096);
411	        if (reply)
412	            tool_registry_execute("get_weather", input, reply, 4096);
413	        if (reply) {
414	            s_fast_path_count++;
415	            syslog(LOG_INFO,
416	                "[%s] NL fast path: get_weather (fast=%d llm=%d)\n",
417	                TAG, s_fast_path_count, s_llm_path_count);
418	        }
419	        return reply;
420	    }
421	
422	    /* Music play (special: needs keyword extraction) */
423	    static const char* kw_play[] = { "播放", "play ", "放一首", NULL };
424	    if (contains_any(text, kw_play)) {
425	        const char* kw = NULL;
426	        const char* p = strstr(text, "播放");
427	        if (p) { p += strlen("播放"); while (*p == ' ') p++; if (*p) kw = p; }
428	        if (!kw) {
429	            p = strcasestr(text, "play ");
430	            if (p) { p += 5; while (*p == ' ') p++; if (*p) kw = p; }
431	        }
432	        if (kw) {
433	            int klen = 0;
434	            while (kw[klen] && kw[klen] != '"' && kw[klen] != '\\' && klen < 100)
435	                klen++;
436	            char input[256];
437	            snprintf(input, sizeof(input),
438	                "{\"keyword\":\"%.*s\"}", klen, kw);
439	            char search_result[4096];
440	            memset(search_result, 0, sizeof(search_result));
441	            tool_registry_execute("music_search", input, search_result, sizeof(search_result));
442	
443	            /* Auto-play first result if search succeeded */
444	            char* reply = NULL;
445	            cJSON* sr = cJSON_Parse(search_result);
446	            cJSON* songs = sr ? cJSON_GetObjectItem(sr, "songs") : NULL;
447	            cJSON* first = songs ? cJSON_GetArrayItem(songs, 0) : NULL;
448	            cJSON* url = first ? cJSON_GetObjectItem(first, "url") : NULL;
449	            if (url && cJSON_IsString(url) && url->valuestring[0]) {
450	                char play_input[512];
451	                snprintf(play_input, sizeof(play_input),
452	                    "{\"url\":\"%s\"}", url->valuestring);
453	                char play_result[256];
454	                memset(play_result, 0, sizeof(play_result));
455	                tool_registry_execute("music_play", play_input, play_result, sizeof(play_result));
456	
457	                /* Build reply with song info */
458	                cJSON* name = cJSON_GetObjectItem(first, "name");
459	                cJSON* artist = cJSON_GetObjectItem(first, "artist");
460	                const char* sname = (name && cJSON_IsString(name)) ? name->valuestring : "未知";
461	                const char* sartist = (artist && cJSON_IsString(artist)) ? artist->valuestring : "未知";
462	
463	                /* Check if play actually succeeded */
464	                bool play_ok = (strstr(play_result, "error") == NULL && play_result[0] != '\0');
465	                reply = calloc(1, 512);
466	                if (reply) {
467	                    if (play_ok) {
468	                        snprintf(reply, 512, "正在播放: %s - %s", sname, sartist);
469	                    } else {
470	                        snprintf(reply, 512, "找到了 %s - %s，但播放失败: %s",
471	                            sname, sartist, play_result);
472	                    }
473	                }
474	            } else {
475	                reply = calloc(1, 4096);
476	                if (reply)
477	                    strncpy(reply, search_result, 4095);
478	            }
479	            cJSON_Delete(sr);
480	
481	            if (reply) {
482	                s_fast_path_count++;
483	                syslog(LOG_INFO,
484	                    "[%s] NL fast path: music_search (fast=%d llm=%d)\n",
485	                    TAG, s_fast_path_count, s_llm_path_count);
486	            }
487	            return reply;
488	        }
489	    }
490	
491	    return NULL;
492	}
