842	
843	static void dispatch_response(const agent_msg_t* msg,
844	    char* final_text)
845	{
846	    if (final_text && final_text[0]) {
847	        session_append(msg->chat_id, "user", msg->content);
848	        session_append(msg->chat_id, "assistant", final_text);
849	
850	        agent_msg_t out = { 0 };
851	        strncpy(out.channel, msg->channel,
852	            sizeof(out.channel) - 1);
853	        strncpy(out.chat_id, msg->chat_id,
854	            sizeof(out.chat_id) - 1);
855	        out.content = final_text;
856	        if (message_bus_push_outbound(&out) != OK) {
857	            free(final_text);
858	        }
859	    } else {
860	        free(final_text);
861	        agent_msg_t out = { 0 };
862	        strncpy(out.channel, msg->channel,
863	            sizeof(out.channel) - 1);
864	        strncpy(out.chat_id, msg->chat_id,
865	            sizeof(out.chat_id) - 1);
866	        out.content = strdup("Sorry, I encountered an error.");
867	        if (out.content) {
868	            if (message_bus_push_outbound(&out) != OK) {
869	                free(out.content);
870	            }
871	        }
872	    }
873	}
