877	static const char* s_working_phrases[] = {
878	    "正在思考中...",
879	    "稍等，处理中...",
880	    "让我查一下...",
881	    "正在分析...",
882	    "马上好...",
883	};
884	#define WORKING_PHRASE_COUNT \
885	    ((int)(sizeof(s_working_phrases) / sizeof(s_working_phrases[0])))
886	
887	/* Send a "working" status message on the first iteration.
888	 * Skip for feishu (has its own typing indicator) and voice
889	 * (TTS synthesis of a status phrase wastes time and memory). */
890	static void send_working_status(const agent_msg_t* msg, int iteration)
891	{
892	    if (iteration != 0) {
893	        return;
894	    }
895	    if (strcmp(msg->channel, AGENT_CHAN_FEISHU) == 0
896	        || strcmp(msg->channel, AGENT_CHAN_VOICE) == 0
897	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
898	        || strcmp(msg->channel, AGENT_CHAN_QUICKAPP) == 0
899	#endif
900	        || strcmp(msg->channel, AGENT_CHAN_WEIXIN) == 0) {
901	        return;
902	    }
903	
904	    agent_msg_t status = { 0 };
905	
906	    strncpy(status.channel, msg->channel, sizeof(status.channel) - 1);
907	    strncpy(status.chat_id, msg->chat_id, sizeof(status.chat_id) - 1);
908	    status.content = strdup(
909	        s_working_phrases[(unsigned)rand() % WORKING_PHRASE_COUNT]);
910	    if (status.content) {
911	        if (message_bus_push_outbound(&status) != OK) {
912	            free(status.content);
913	        }
914	    }
915	}
