1360	/* ── Build messages array from session history + current msg ─ */
1361	
1362	static cJSON* build_messages(const char* chat_id, const char* content,
1363	    char* history_json, size_t hist_size)
1364	{
1365	    session_get_history_json(chat_id, history_json, hist_size,
1366	        AGENT_AI_AGENT_MAX_HISTORY);
1367	
1368	    cJSON* messages = cJSON_Parse(history_json);
1369	
1370	    if (!messages) {
1371	        messages = cJSON_CreateArray();
1372	    }
1373	
1374	    cJSON* user_msg = cJSON_CreateObject();
1375	
1376	    cJSON_AddStringToObject(user_msg, "role", "user");
1377	    cJSON_AddStringToObject(user_msg, "content", content);
1378	    cJSON_AddItemToArray(messages, user_msg);
1379	    return messages;
1380	}
