1382	/* ── Inject session context into system prompt ───────────── */
1383	
1384	static void inject_session_context(char* sys_prompt, size_t size,
1385	    const char* channel, const char* chat_id)
1386	{
1387	    size_t len = strlen(sys_prompt);
1388	
1389	    snprintf(sys_prompt + len, size - len,
1390	        "\n## Current Session\n"
1391	        "channel: %s\n"
1392	        "chat_id: %s\n"
1393	        "When using feishu_send_mention or feishu_chat_members, "
1394	        "use the chat_id above unless the user specifies a "
1395	        "different one.\n"
