1404	/* ── Main agent loop task ─────────────────────────────────── */
1405	
1406	static void* agent_loop_task(void* arg)
1407	{
1408	    (void)arg;
1409	    agent_mem_status_t mem_st;
1410	
1411	    agent_mem_get_status(&mem_st);
1412	    syslog(LOG_INFO, "[%s] Agent loop started, free heap: %zu\n",
1413	        TAG, mem_st.free_heap);
1414	
1415	    size_t ctx_size = agent_mem_safe_size(
1416	        AGENT_CONTEXT_BUF_SIZE, 4 * 1024);
1417	    size_t hist_size = agent_mem_safe_size(
1418	        AGENT_LLM_STREAM_BUF_SIZE, 8 * 1024);
1419	    size_t tool_size = agent_mem_safe_size(
1420	        TOOL_OUTPUT_SIZE, TOOL_OUTPUT_SIZE_MIN);
1421	
1422	    char* sys_prompt = calloc(1, ctx_size);
1423	    char* history_json = calloc(1, hist_size);
1424	    char* tool_output = calloc(1, tool_size);
1425	
1426	    if (!sys_prompt || !history_json || !tool_output) {
1427	        syslog(LOG_ERR, "[%s] Failed to allocate agent buffers\n", TAG);
1428	        free(sys_prompt);
1429	        free(history_json);
1430	        free(tool_output);
1431	        return NULL;
1432	    }
1433	
1434	    syslog(LOG_INFO, "[%s] Buffers: ctx=%zu hist=%zu tool=%zu\n",
1435	        TAG, ctx_size, hist_size, tool_size);
1436	
1437	    /* Initialize memory pool for parallel tool outputs */
1438	    size_t pool_buf_size = agent_mem_safe_size(
1439	        TOOL_OUTPUT_SIZE_LARGE, TOOL_OUTPUT_SIZE_MIN);
1440	    if (agent_pool_init(&s_tool_pool, pool_buf_size,
1441	            AGENT_MAX_TOOL_CALLS)
1442	        == OK) {
1443	        s_pool_ready = true;
1444	        syslog(LOG_INFO, "[%s] Tool output pool: %d x %zu bytes\n",
1445	            TAG, AGENT_MAX_TOOL_CALLS, pool_buf_size);
1446	    } else {
1447	        syslog(LOG_WARNING,
1448	            "[%s] Pool init failed, using heap fallback\n", TAG);
1449	    }
1450	
1451	    char* tools_json = tool_registry_get_tools_json();
1452	
1453	    syslog(LOG_INFO, "[%s] Tools JSON loaded: %d bytes\n",
1454	        TAG, tools_json ? (int)strlen(tools_json) : 0);
1455	
1456	    while (!agent_shutdown_requested()) {
1457	        agent_msg_t msg;
1458	        int err = message_bus_pop_inbound(&msg, UINT32_MAX);
1459	
1460	        if (err != OK) {
1461	            continue;
1462	        }
1463	
1464	        if (agent_shutdown_requested()) {
1465	            free(msg.content);
1466	            free(msg.image_b64);
1467	            break;
1468	        }
1469	
1470	        syslog(LOG_INFO, "[%s] Processing message from %s:%s\n",
1471	            TAG, msg.channel, msg.chat_id);
1472	
1473	        /* Check memory pressure */
1474	        agent_mem_get_status(&mem_st);
1475	        if (mem_st.free_heap < AGENT_MEM_RESERVE_BYTES) {
1476	            syslog(LOG_WARNING,
1477	                "[%s] Low memory: %zu bytes free, skipping\n",
1478	                TAG, mem_st.free_heap);
1479	            agent_msg_t out = { 0 };
1480	            strncpy(out.channel, msg.channel,
1481	                sizeof(out.channel) - 1);
1482	            strncpy(out.chat_id, msg.chat_id,
1483	                sizeof(out.chat_id) - 1);
1484	            out.content = strdup("系统内存不足，请稍后再试。");
1485	            if (out.content) {
1486	                if (message_bus_push_outbound(&out) != OK) {
1487	                    free(out.content);
1488	                }
1489	            }
1490	            free(msg.content);
1491	            continue;
1492	        }
1493	
1494	        /* Slash commands — fast path, bypass LLM */
1495	        char* reply = handle_slash_command(&msg);
1496	
1497	        /* Prompt injection check — before LLM */
1498	        if (!reply && tool_guard_check_injection(msg.content)) {
1499	            syslog(LOG_WARNING,
1500	                "[%s] Prompt injection blocked from %s:%s\n",
1501	                TAG, msg.channel, msg.chat_id);
1502	            reply = strdup("I can't do that.");
1503	            if (!reply) {
1504	                /* Fail-closed: skip this message entirely */
1505	                free(msg.content);
1506	                continue;
1507	            }
1508	        }
1509	
1510	        /* NL fast path — after injection check, before LLM */
1511	        if (!reply) {
1512	            reply = handle_nl_fast_path(msg.content);
1513	        }
1514	
1515	        if (reply) {
1516	            agent_msg_t out = { 0 };
1517	            strncpy(out.channel, msg.channel,
1518	                sizeof(out.channel) - 1);
1519	            strncpy(out.chat_id, msg.chat_id,
1520	                sizeof(out.chat_id) - 1);
1521	            out.content = reply;
1522	            if (message_bus_push_outbound(&out) != OK) {
1523	                free(reply);
1524	            }
1525	            free(msg.content);
1526	            continue;
1527	        }
1528	
1529	        /* Hot-reload skills if directory changed */
1530	        if (skill_loader_check_changed()) {
1531	            syslog(LOG_INFO, "[%s] Skills changed, refreshing\n", TAG);
1532	            skill_loader_refresh();
1533	        }
1534	
1535	        context_build_system_prompt(sys_prompt, ctx_size);
1536	        inject_session_context(sys_prompt, ctx_size,
1537	            msg.channel, msg.chat_id);
1538	
1539	        /* Refresh tools JSON — Node tools are dynamic */
1540	        free(tools_json);
1541	        tools_json = tool_registry_get_tools_json();
1542	
1543	        cJSON* messages = build_messages(msg.chat_id, msg.content,
1544	            history_json, hist_size);
1545	
1546	        char* final_text = NULL;
1547	
1548	        /* Vision path */
1549	        final_text = handle_vision_message(&msg);
1550	        if (final_text) {
1551	            cJSON_Delete(messages);
1552	        } else {
1553	            /* ReAct loop */
1554	            s_llm_path_count++;
1555	            final_text = run_react_loop(sys_prompt, messages,
1556	                tools_json, tool_output, tool_size, &msg);
1557	            cJSON_Delete(messages);
1558	        }
1559	
1560	        dispatch_response(&msg, final_text);
1561	
1562	        /* Free image_b64 if not already freed by vision path */
1563	        free(msg.image_b64);
1564	        msg.image_b64 = NULL;
1565	        free(msg.content);
1566	    }
1567	
1568	    /* Cleanup (unreachable in normal operation) */
1569	    if (s_pool_ready) {
1570	        agent_pool_destroy(&s_tool_pool);
1571	        s_pool_ready = false;
1572	    }
1573	    free(tools_json);
1574	    free(sys_prompt);
1575	    free(history_json);
1576	    free(tool_output);
1577	    return NULL;
1578	}
