46	static void uv__acync_queue_cb(uv_async_t* async)
47	{
48	    uv_async_queue_t* async_queue = async->data;
49	    struct uv__async_queue_handle_s* queue_handle;
50	    struct uv__queue* node;
51	    struct uv__queue local_queue;
52	
53	    uv__queue_init(&local_queue);
54	
55	    /* Move data to a temporary queue */
56	
57	    uv_mutex_lock(&async_queue->mutex);
58	    uv__queue_move(&async_queue->queue, &local_queue);
59	    uv_mutex_unlock(&async_queue->mutex);
60	
61	    /* Process data in the temporary queue, no longer check the original queue */
62	
63	    while (!uv__queue_empty(&local_queue)) {
64	        node = uv__queue_head(&local_queue);
65	        queue_handle = uv__queue_data(node, struct uv__async_queue_handle_s, node);
66	        uv__queue_remove(node);
67	        async_queue->cb(async_queue, queue_handle->data);
68	        free(queue_handle);
69	    }
70	}
