80	int uv_async_queue_init(uv_loop_t* loop, uv_async_queue_t* async_queue,
81	    uv_async_queue_cb async_queue_cb)
82	{
83	    int ret;
84	
85	    ret = uv_async_init(loop, &async_queue->async, uv__acync_queue_cb);
86	    if (ret != 0) {
87	        uv_queue_error("async init failed, %d", ret);
88	        return ret;
89	    }
90	
91	    uv_queue_debug("uv_async_queue_init");
92	    async_queue->cb = async_queue_cb;
93	    async_queue->async.data = async_queue;
94	    uv_mutex_init(&async_queue->mutex);
95	    uv__queue_init(&async_queue->queue);
96	    return ret;
97	}
