103	int uv_async_queue_send(uv_async_queue_t* async_queue, void* data)
104	{
105	    int ret;
106	
107	    struct uv__async_queue_handle_s* handle = malloc(sizeof(*handle));
108	    handle->data = data;
109	    uv_mutex_lock(&async_queue->mutex);
110	    uv__queue_insert_tail(&async_queue->queue, &handle->node);
111	    uv_mutex_unlock(&async_queue->mutex);
112	    ret = uv_async_send(&async_queue->async);
113	    if (ret != 0) {
114	        uv_queue_error("async init failed, %d", ret);
115	    }
116	
117	    return ret;
118	}
