124	void uv_async_queue_close(uv_async_queue_t* async_queue, uv_close_cb cb)
125	{
126	    struct uv__async_queue_handle_s* queue_handle;
127	    struct uv__queue* node;
128	
129	    uv_mutex_lock(&async_queue->mutex);
130	    while (!uv__queue_empty(&async_queue->queue)) {
131	        node = uv__queue_head(&async_queue->queue);
132	        queue_handle = uv__queue_data(node, struct uv__async_queue_handle_s, node);
133	        uv__queue_remove(node);
134	        uv_queue_error("data is discarded: %p", queue_handle->data);
135	        free(queue_handle);
136	    }
137	
138	    uv_queue_debug("uv_async_queue_close");
139	    uv_mutex_unlock(&async_queue->mutex);
140	    uv_mutex_destroy(&async_queue->mutex);
141	    uv_close((uv_handle_t*)&async_queue->async, cb);
142	}
