198	void message_bus_wakeup(void)
199	{
200	    g_bus_shutdown = true;
201	
202	    pthread_mutex_lock(&g_inbound_queue.lock);
203	    pthread_cond_broadcast(&g_inbound_queue.not_empty);
204	    pthread_mutex_unlock(&g_inbound_queue.lock);
205	
206	    pthread_mutex_lock(&g_outbound_queue.lock);
207	    pthread_cond_broadcast(&g_outbound_queue.not_empty);
208	    pthread_mutex_unlock(&g_outbound_queue.lock);
209	}
