120	    if (fd < 0) fd = open("/dev/random", O_RDONLY);
121	    if (fd < 0) return -1;
122	
123	    unsigned char *p = (unsigned char *)buf;
124	    size_t remaining = len;
125	
126	    while (remaining > 0) {
127	        ssize_t n = read(fd, p, remaining);
128	        if (n > 0) {
129	            p += n;
130	            remaining -= (size_t)n;
