BOOT_LOG(&t0, "P5", "cron + heartbeat started");

注意：这里 cron_service_start() 的返回值没有被检查。

packages/ai_agent/src/infra/cron_service.c

static void cron_process_due_jobs(void)
{
    time_t now = time(NULL);
    bool changed = false;

    pthread_mutex_lock(&s_cron_lock);

    for (int i = 0; i < s_job_count; i++) {
        cron_job_t* job = &s_jobs[i];

        syslog(LOG_DEBUG,
            "[%s] Check job[%d] '%s': enabled=%d next_run=%lld now=%lld\n",
            TAG, i, job->name, job->enabled,
            (long long)job->next_run, (long long)now);

        if (!job->enabled || job->next_run <= 0 || job->next_run > now) {
            continue;
        }

        cron_fire_job(job, now);

        if (job->kind == CRON_KIND_AT) {
            if (job->delete_after_run) {
                ...
                s_job_count--;
                i--;
            } else {
                job->enabled = false;
                job->next_run = 0;
            }
        } else {
            job->next_run = now + job->interval_s;
        }

        changed = true;
    }

    if (changed) {
        cron_save_jobs();
    }

    pthread_mutex_unlock(&s_cron_lock);
}

cron 线程：

static void* cron_task_main(void* arg)
{
    (void)arg;

    while (s_cron_running) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += AGENT_CRON_CHECK_INTERVAL_MS / 1000;

        pthread_mutex_lock(&s_cron_lock);
        pthread_cond_timedwait(&s_cron_wake, &s_cron_lock, &ts);
        pthread_mutex_unlock(&s_cron_lock);

        cron_process_due_jobs();
    }

    return NULL;
}

cron_service_start()：

int cron_service_start(void)
{
    pthread_mutex_lock(&s_cron_lock);

    if (s_cron_running) {
        pthread_mutex_unlock(&s_cron_lock);
        syslog(LOG_WARNING, "[%s] Cron task already running\n", TAG);
        return OK;
    }

    time_t now = time(NULL);
    bool changed = false;

    for (int i = 0; i < s_job_count; i++) {
        cron_job_t* job = &s_jobs[i];

        if (!job->enabled) {
            continue;
        }

        if (job->next_run > 0 && job->next_run <= now) {
            syslog(LOG_WARNING,
                "[%s] disabling stale job: %s (next_run %lld <= now %lld)\n",
                TAG, job->name,
                (long long)job->next_run,
                (long long)now);
            job->enabled = false;
            job->next_run = 0;
            changed = true;
            continue;
        }

        if (job->next_run <= 0) {
            if (job->kind == CRON_KIND_EVERY) {
                job->next_run = now + job->interval_s;
            } else if (job->kind == CRON_KIND_AT && job->at_epoch > now) {
                job->next_run = job->at_epoch;
            }
        }
    }

    if (changed) {
        cron_save_jobs();
    }

    s_cron_running = true;
    pthread_mutex_unlock(&s_cron_lock);

    int err = agent_task_create(
        cron_task_main,
        "cron",
        AGENT_CRON_STACK,
        NULL,
        AGENT_CRON_PRIO);

    if (err != OK) {
        s_cron_running = false;
        syslog(LOG_ERR, "[%s] Failed to create cron task\n", TAG);
        return ERROR;
    }

    syslog(LOG_INFO,
        "[%s] Cron started (%d jobs, interval %ds)\n",
        TAG, ...);

    return OK;
}

