49	typedef struct {
50	    void* (*func)(void*);
51	    void* arg;
52	    int stack_size;
53	} _agent_task_args_t;
54	
55	static inline void* _agent_task_shim(void* p)
56	{
57	    _agent_task_args_t* ta = (_agent_task_args_t*)p;
58	    void* (*f)(void*) = ta->func;
59	    void* a = ta->arg;
60	    free(ta);
61	    return f(a);
62	}
