64	/**
65	 * Create a detached POSIX thread.
66	 * Returns OK (0) on success, ERROR (-1) on failure.
67	 */
68	static inline int agent_task_create(void* (*func)(void*), const char* name,
69	    int stack_size, void* arg, int prio)
70	{
71	    (void)name;
72	
73	    _agent_task_args_t* ta = malloc(sizeof(_agent_task_args_t));
74	    if (!ta)
75	        return ERROR;
76	    ta->func = func;
77	    ta->arg = arg;
78	    ta->stack_size = stack_size;
79	
80	    pthread_attr_t attr;
81	    pthread_attr_init(&attr);
82	    pthread_attr_setstacksize(&attr, (size_t)(stack_size < 4096 ? 4096 : stack_size));
83	
84	    /* Set thread priority via SCHED_FIFO (NuttX supports this) */
85	    struct sched_param sp;
86	    sp.sched_priority = prio;
87	    pthread_attr_setschedparam(&attr, &sp);
88	    pthread_attr_setschedpolicy(&attr, SCHED_FIFO);
89	    pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
90	
91	    pthread_t tid;
92	    int r = pthread_create(&tid, &attr, _agent_task_shim, ta);
93	    pthread_attr_destroy(&attr);
94	    if (r != 0) {
95	        free(ta);
96	        return ERROR;
97	    }
98	    pthread_detach(tid);
99	    return OK;
100	}
