103	
104	#include <fcntl.h>
105	
106	/**
107	 * Fill buffer with cryptographically secure random bytes.
108	 * Uses /dev/urandom (preferred) or /dev/random as fallback.
109	 *
110	 * SECURITY: This function will block or fail rather than return
111	 * predictable data. For TLS entropy, this is the correct behavior.
112	 *
113	 * Returns 0 on success, -1 on failure (caller must handle).
114	 */
115	static inline int agent_secure_random(void *buf, size_t len)
116	{
117	    if (len == 0) return 0;
118	
119	    int fd = open("/dev/urandom", O_RDONLY);
120	    if (fd < 0) fd = open("/dev/random", O_RDONLY);
121	    if (fd < 0) return -1;
122	
123	    unsigned char *p = (unsigned char *)buf;
124	    size_t remaining = len;
125	
126	    while (remaining > 0) {
127	        ssize_t n = read(fd, p, remaining);
128	        if (n > 0) {
129	            p += n;
130	            remaining -= (size_t)n;
131	        } else if (n == 0) {
132	            /* EOF on random device — should not happen */
133	            close(fd);
134	            return -1;
135	        } else if (errno != EINTR) {
136	            /* Real error */
137	            close(fd);
138	            return -1;
139	        }
140	        /* EINTR: retry */
141	    }
142	
143	    close(fd);
144	    return 0;
145	}
