124	int tool_cron_add_execute(const char* input_json,
125	    char* output, size_t output_size)
126	{
127	    cJSON* root = cJSON_Parse(input_json);
128	
129	    if (!root) {
130	        snprintf(output, output_size, "Error: invalid JSON input");
131	        return ERROR;
132	    }
133	
134	    const char* name = cJSON_GetStringValue(
135	        cJSON_GetObjectItem(root, "name"));
136	    const char* schedule_type = cJSON_GetStringValue(
137	        cJSON_GetObjectItem(root, "schedule_type"));
138	    const char* message = cJSON_GetStringValue(
139	        cJSON_GetObjectItem(root, "message"));
140	
